"use strict";
(()=>{const q=s=>document.querySelector(s),track=q('#review-track'),button=q('#pause-reviews');let paused=false;
button.onclick=()=>{paused=!paused;track.classList.toggle('paused',paused);button.textContent=paused?'Riprendi scorrimento':'Pausa scorrimento';button.setAttribute('aria-pressed',String(paused))};
fetch('/api/site-reviews').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{q('#reviews-empty').hidden=!!data.reviews.length;for(const review of data.reviews){const card=document.createElement('article');card.className='review-card';const stars=document.createElement('p');stars.className='review-score';stars.textContent='★'.repeat(review.rating)+'☆'.repeat(5-review.rating);stars.setAttribute('aria-label',review.rating+' su 5');const text=document.createElement('blockquote');text.textContent=review.comment;const name=document.createElement('strong');name.textContent=review.name;card.append(stars,text,name);track.append(card)}if(data.reviews.length>2){button.hidden=false;const distance=Math.max(0,track.scrollWidth-q('#review-showcase').clientWidth);track.style.setProperty('--travel','-'+distance+'px');track.classList.add('moving');new ResizeObserver(()=>track.style.setProperty('--travel','-'+Math.max(0,track.scrollWidth-q('#review-showcase').clientWidth)+'px')).observe(q('#review-showcase'))}}).catch(()=>q('#reviews-empty').textContent='Le recensioni non sono disponibili al momento. Riprova tra poco.');
q('#review-form').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button[type=submit]');b.disabled=true;const fields=new FormData(form);try{const r=await fetch('/api/site-reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fields.get('name'),rating:Number(fields.get('rating')),comment:fields.get('comment'),consent:fields.get('consent')==='on'})});const d=await r.json();if(!r.ok)throw Error(d.error);q('#review-status').textContent='Grazie! La recensione è stata ricevuta e sarà visibile dopo la revisione.';form.reset()}catch(err){q('#review-status').textContent=err.message||'Invio non riuscito. Riprova.'}finally{b.disabled=false}};
})();